#[test]
fn whole_document_replacement_is_one_undo_entry_and_never_crosses_a_gesture() {
    let original = map();
    let mut replacement = original.clone();
    replacement.chunk_size = 16;
    let mut service = TileMapAuthoringService::new(original.clone());

    assert!(service.replace_document(replacement.clone()).unwrap());
    assert_eq!(service.document(), &replacement);
    assert!(service.undo());
    assert_eq!(service.document(), &original);

    service.begin_gesture().unwrap();
    assert!(matches!(
        service.replace_document(replacement),
        Err(Native2dAuthoringError::GestureAlreadyActive)
    ));
    service.cancel_gesture().unwrap();
}

